'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import {
  HomeIcon,
  BuildingOfficeIcon,
  ShoppingCartIcon,
  AdjustmentsHorizontalIcon,
  ChartBarIcon,
  Cog6ToothIcon,
  ArrowRightOnRectangleIcon,
  UserIcon,
  UserGroupIcon,
  CubeIcon,
  BanknotesIcon,
  ArrowsRightLeftIcon,
  ClipboardDocumentCheckIcon,
  ShieldCheckIcon,
  ChevronLeftIcon,
  ChevronRightIcon
} from '@heroicons/react/24/outline';
import { cn } from '@/lib/utils';

const navigationGroups = [
  {
    title: 'Main',
    items: [
      { name: 'Dashboard', href: '/dashboard', icon: HomeIcon },
      { name: 'Analytics', href: '/analytics', icon: ChartBarIcon },
      { name: 'Reports', href: '/reports', icon: ClipboardDocumentCheckIcon },
    ]
  },
  {
    title: 'Sales & Operations',
    items: [
      { name: 'Point of Sale', href: '/pos', icon: ShoppingCartIcon },
      { name: 'Sales History', href: '/sales', icon: BanknotesIcon },
    ]
  },
  {
    title: 'Inventory',
    items: [
      { name: 'Products', href: '/products', icon: CubeIcon },
      { name: 'Stock Levels', href: '/inventory', icon: AdjustmentsHorizontalIcon },
      { name: 'Transfers', href: '/transfers', icon: ArrowsRightLeftIcon },
    ]
  },
  {
    title: 'Management',
    items: [
      { name: 'Customers', href: '/customers', icon: UserIcon },
      { name: 'Users (Staff)', href: '/users', icon: UserGroupIcon },
      { name: 'Branches', href: '/branches', icon: BuildingOfficeIcon },
      { name: 'Audit Logs', href: '/audit', icon: ShieldCheckIcon },
      { name: 'Settings', href: '/settings', icon: Cog6ToothIcon },
    ]
  },
];

interface SidebarProps {
  onClose?: () => void;
  onToggleMinimize?: () => void;
  isMinimized?: boolean;
}

export default function Sidebar({ onClose, onToggleMinimize, isMinimized = false }: SidebarProps) {
  const pathname = usePathname();

  const handleLogout = () => {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    document.cookie = 'access_token=; path=/; max-age=0';
    document.cookie = 'refresh_token=; path=/; max-age=0';
    window.location.href = '/login';
  };

  return (
    <div className="flex flex-col h-screen bg-surface border-r border-divider">
      {/* Logo */}
      <div className="flex items-center h-16 px-4 bg-card border-b border-divider shrink-0">
        <div className="flex items-center space-x-3 flex-1">
          <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center shrink-0">
            <span className="text-white text-sm font-bold">P</span>
          </div>
          <h1 className={cn(
            "text-xl font-bold text-primary transition-all duration-300",
            isMinimized ? "hidden" : "hidden sm:block"
          )}>POS</h1>
        </div>

        {/* Toggle button - only show on desktop */}
        <button
          onClick={onToggleMinimize}
          className="hidden lg:flex items-center justify-center w-6 h-6 rounded-md hover:bg-surface transition-colors"
        >
          {isMinimized ? (
            <ChevronRightIcon className="w-4 h-4 text-text-secondary" />
          ) : (
            <ChevronLeftIcon className="w-4 h-4 text-text-secondary" />
          )}
        </button>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-3 py-4 space-y-8 overflow-y-auto no-scrollbar">
        {navigationGroups.map((group) => (
          <div key={group.title} className="space-y-2">
            <h3 className={cn(
              "px-3 text-[10px] font-black text-text-secondary/50 uppercase tracking-[0.2em] transition-all duration-300",
              isMinimized ? "hidden" : "block"
            )}>
              {group.title}
            </h3>
            <div className="space-y-1">
              {group.items.map((item) => {
                const isActive = pathname === item.href;
                return (
                  <Link
                    key={item.name}
                    href={item.href}
                    onClick={onClose}
                    className={cn(
                      'group flex items-center px-3 py-2 text-sm font-bold rounded-xl transition-all duration-200',
                      isActive
                        ? 'bg-primary text-white shadow-lg shadow-primary/20'
                        : 'text-text-secondary hover:bg-surface hover:text-primary',
                      isMinimized ? 'justify-center' : 'justify-start'
                    )}
                    title={isMinimized ? item.name : undefined}
                  >
                    <item.icon
                      className={cn(
                        'transition-colors shrink-0',
                        isMinimized ? 'h-5 w-5' : 'mr-3 h-5 w-5',
                        isActive ? 'text-white' : 'text-text-secondary group-hover:text-primary'
                      )}
                      aria-hidden="true"
                    />
                    <span className={cn(
                      "truncate transition-all duration-300",
                      isMinimized ? "hidden" : "block"
                    )}>{item.name}</span>
                  </Link>
                );
              })}
            </div>
          </div>
        ))}
      </nav>

      {/* Logout */}
      <div className="p-4 border-t border-divider shrink-0 bg-card">
        <button
          onClick={handleLogout}
          className={cn(
            "group flex items-center w-full px-4 py-3 text-xs font-black text-text-secondary uppercase tracking-widest rounded-xl hover:bg-error/5 hover:text-error transition-all duration-200 border border-transparent hover:border-error/10",
            isMinimized ? "justify-center px-2" : "justify-start"
          )}
          title={isMinimized ? "Log Out" : undefined}
        >
          <ArrowRightOnRectangleIcon className={cn(
            "text-text-secondary group-hover:text-error shrink-0",
            isMinimized ? "h-5 w-5" : "mr-3 h-5 w-5"
          )} />
          <span className={cn(
            "transition-all duration-300",
            isMinimized ? "hidden" : "block"
          )}>Log Out</span>
        </button>
      </div>
    </div>
  );
}
